const status=s=>$('status').textContent=s;
function prefs(k,v){try{if(v!==undefined)localStorage.setItem(k,v);else return localStorage.getItem(k)}catch{} }
$('sensitivity').value=prefs('sensitivity')||60;
viewCount=Number(prefs('viewCount'))===2?2:1;$('viewMode').value=String(viewCount);
readingDirection=prefs('readingDirection')==='rtl'?'rtl':'ltr';$('readingDirection').value=readingDirection;
function mask(data,level){const p=data.data,limit=35-level*.3;for(let i=0;i<p.length;i+=4){const r=p[i],g=p[i+1],b=p[i+2];if(r>95&&r-g>limit&&r-b>limit*.65){p[i]=p[i+1]=p[i+2]=255;}}return data}
function paint(){if(epubSecond)epubSecond.paint(hidden&&!peeking,+$('sensitivity').value);if(epub)epub.paint(hidden&&!peeking,+$('sensitivity').value);if(!raw&&!epub)return;if(!epub){const copy=new ImageData(new Uint8ClampedArray(raw.data),raw.width,raw.height);ctx.putImageData(hidden&&!peeking?mask(copy,+$('sensitivity').value):copy,0,0);}$('toggle').textContent=hidden?'◉ 정답 보기':'◉ 정답 숨기기';$('toggle').setAttribute('aria-pressed',String(hidden));$('badge').textContent=hidden&&!peeking?'정답 숨김':'정답 표시';$('strength').value=$('sensitivity').value;}
function applyDirection(){if(epub)epub.frame.style.order=readingDirection==='rtl'&&epubSecond?'2':'0';if(epubSecond)epubSecond.frame.style.order=readingDirection==='rtl'?'1':'2';$('readingDirection').disabled=viewCount!==2||total<2;}
function size(){applyDirection();if(epub)epub.size(zoom);if(epubSecond)epubSecond.size(zoom);const w=Math.max(150,$('viewport').clientWidth);canvas.style.width=Math.round(w*zoom)+'px';canvas.style.height='auto';$('zoomLabel').textContent=Math.round(zoom*100)+'%'}
function demo(){ctx.fillStyle='#fffdf6';ctx.fillRect(0,0,1100,1450);ctx.fillStyle='#a83c35';ctx.font='22px sans-serif';ctx.fillText('漢字検定 ２級　／　書き取り',90,100);ctx.fillStyle='#333b30';ctx.font='46px serif';ctx.fillText('今日の一歩が、明日の力に。',90,210);ctx.font='23px sans-serif';ctx.fillText('次のカタカナを漢字に直しましょう。',90,290);const rows=[['01','自然のオンケイを受ける。','恩恵'],['02','物事のホンシツを見極める。','本質'],['03','困難をコクフクする。','克服'],['04','自分の意見をシュチョウする。','主張'],['05','学習をケイゾクする。','継続']];rows.forEach((r,i)=>{let y=415+i*180;ctx.fillStyle='#888d7b';ctx.font='20px sans-serif';ctx.fillText(r[0],90,y);ctx.fillStyle='#333b30';ctx.font='32px serif';ctx.fillText(r[1],155,y);ctx.strokeStyle='#dddccf';ctx.beginPath();ctx.moveTo(155,y+100);ctx.lineTo(980,y+100);ctx.stroke();ctx.fillStyle='#df5043';ctx.font='42px serif';ctx.fillText(r[2],175,y+75)});ctx.fillStyle='#90947f';ctx.font='18px sans-serif';ctx.fillText('赤シート　·　체험용으로 제작한 예제입니다.',90,1380)}
async function render(){if(busy)return;busy=true;const token=++sequence;$('prev').disabled=$('next').disabled=true;try{if(epub){status('EPUB 본문을 준비하고 있습니다…');await epub.show(page);if(viewCount===2&&page<total){if(!epubSecond)epubSecond=new LocalEpub(epub.zip,epub.chapters,epub.types);await epubSecond.show(page+1)}else if(epubSecond){epubSecond.destroy();epubSecond=null;canvas.hidden=true;}}else if(pdf){status('페이지를 준비하고 있습니다…');const sheets=[];for(let n=page;n<=Math.min(total,page+viewCount-1);n++){const p=await pdf.getPage(n);const base=p.getViewport({scale:1});const v=p.getViewport({scale:Math.min(2,1600/Math.max(base.width,base.height))});const c=document.createElement('canvas');c.width=Math.ceil(v.width);c.height=Math.ceil(v.height);await p.render({canvasContext:c.getContext('2d'),viewport:v}).promise;sheets.push(c)}canvas.width=sheets.reduce((w,c)=>w+c.width,0);canvas.height=Math.max(...sheets.map(c=>c.height));ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);if(readingDirection==='rtl')sheets.reverse();let x=0;for(const c of sheets){ctx.drawImage(c,x,0);x+=c.width}}else if(img){const s=Math.min(1,1800/Math.max(img.width,img.height));canvas.width=Math.round(img.width*s);canvas.height=Math.round(img.height*s);ctx.drawImage(img,0,0,canvas.width,canvas.height);}else{canvas.width=1100;canvas.height=1450;demo()}if(token!==sequence)return;if(!epub)raw=ctx.getImageData(0,0,canvas.width,canvas.height);paint();size();$('number').value=page;$('number').max=total;$('total').textContent=total;$('viewMode').disabled=total<2;if(fileKey)prefs('page:'+fileKey,page);$('number').setAttribute('aria-label',epub?'본문 번호':'페이지 번호');status(epub||pdf?'맨 아래·맨 위에서 계속 스크롤하면 다음·이전 페이지로 이동합니다.'+(viewCount===2?' 현재 '+page+'–'+Math.min(total,page+1)+' / '+total:''):img?'빨간 글씨가 남으면 숨김 감도를 조절하세요.':'예제의 빨간 정답이 숨겨져 있습니다. 내 책을 열어 시작하세요.');}catch(e){status('페이지를 표시하지 못했습니다: '+e.message)}finally{busy=false;positionPages(arrivalBottom);arrivalBottom=false;scrollLock=Date.now()+700;$('prev').disabled=page<=1;$('next').disabled=page+viewCount>total;}}
async function open(file){if(!file||busy)return;busy=true;status('파일을 여는 중입니다…');let url;try{let newPdf=null,newImg=null,newEpub=null;if(/\.epub$/i.test(file.name)||file.type==='application/epub+zip'){newEpub=await LocalEpub.load(file);}else if(file.type==='application/pdf'||/\.pdf$/i.test(file.name)){newPdf=await pdfjsLib.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false}).promise;}else if(/^image\//.test(file.type)){url=URL.createObjectURL(file);newImg=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('이미지를 읽을 수 없습니다. PNG 또는 JPEG로 변환해 주세요.'));i.src=url});}else throw Error('EPUB, PDF, PNG, JPEG, WebP 파일을 선택해 주세요.');if(pdf)await pdf.destroy();if(epubSecond){epubSecond.destroy();epubSecond=null;}if(epub)epub.destroy();epub=newEpub;pdf=newPdf;img=newImg;canvas.hidden=!!epub;total=epub?epub.chapters.length:pdf?pdf.numPages:1;fileKey=file.name+':'+file.size+':'+file.lastModified;page=Math.min(total,Math.max(1,Number(prefs('page:'+fileKey))||1));$('filename').textContent=file.name;zoom=1;hidden=true;}catch(e){status(e.name==='PasswordException'?'암호가 걸린 PDF입니다. 암호를 해제한 사본을 열어 주세요.':'파일을 열지 못했습니다: '+e.message);return}finally{if(url)URL.revokeObjectURL(url);busy=false;$('file').value=''}await render()}
function positionPages(bottom){const outer=$('viewport');outer.scrollTop=bottom?outer.scrollHeight:0;for(const book of [epub,epubSecond]){const d=book?.frame.contentDocument;if(d){const e=d.scrollingElement;const w=book.frame.contentWindow;w.scrollTo(w.scrollX,bottom?e.scrollHeight:0)}}}
function boundaryMove(delta,scroller){if(busy||Date.now()<scrollLock||total<2)return false;const down=delta>0,edge=down?scroller.scrollTop+scroller.clientHeight>=scroller.scrollHeight-3:scroller.scrollTop<=3;if(!edge){scrollSum=0;return false}const now=Date.now();if(now-scrollTime>250||Math.sign(scrollSum)!==Math.sign(delta))scrollSum=0;scrollTime=now;scrollSum+=delta;if(Math.abs(scrollSum)<90)return false;if((down&&page+viewCount<=total)||(!down&&page>1)){go(page+(down?viewCount:-viewCount),!down);return true}return false}
function bindPageScroll(target,getScroller){let touch=null;target.addEventListener('wheel',e=>{if(Math.abs(e.deltaY)<=Math.abs(e.deltaX)||e.ctrlKey)return;const delta=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?500:1);if(boundaryMove(delta,getScroller()))e.preventDefault()},{passive:false});target.addEventListener('touchstart',e=>{if(e.touches.length!==1){touch=null;return}const s=getScroller();touch={y:e.touches[0].clientY,x:e.touches[0].clientX,top:s.scrollTop<=3,bottom:s.scrollTop+s.clientHeight>=s.scrollHeight-3}},{passive:true});target.addEventListener('touchend',e=>{if(!touch||!e.changedTouches.length)return;const dy=touch.y-e.changedTouches[0].clientY,dx=touch.x-e.changedTouches[0].clientX;if(Math.abs(dy)>70&&Math.abs(dy)>Math.abs(dx)&&((dy>0&&touch.bottom)||(dy<0&&touch.top)))boundaryMove(Math.sign(dy)*100,getScroller());touch=null},{passive:true})}
bindPageScroll($('viewport'),()=>$('viewport'));
$('file').onchange=e=>open(e.target.files[0]);$('toggle').onclick=()=>{hidden=!hidden;paint()};
$('peek').onpointerdown=e=>{e.preventDefault();$('peek').setPointerCapture(e.pointerId);peeking=true;paint()};for(const event of ['pointerup','pointercancel','lostpointercapture'])$('peek').addEventListener(event,()=>{peeking=false;paint()});$('peek').onkeydown=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();peeking=true;paint()}};$('peek').onkeyup=()=>{peeking=false;paint()};window.onblur=()=>{peeking=false;paint()};
$('sensitivity').oninput=()=>{prefs('sensitivity',$('sensitivity').value);paint()};function go(n,bottom=false){if(busy)return;const target=Math.min(total,Math.max(1,n||1));if(target===page)return;arrivalBottom=bottom;page=target;scrollLock=Date.now()+1200;scrollSum=0;render()}$('prev').onclick=()=>go(page-viewCount);$('next').onclick=()=>go(page+viewCount);$('number').onchange=e=>go(Number(e.target.value));$('plus').onclick=()=>{zoom=Math.min(3,zoom+.25);size()};$('minus').onclick=()=>{zoom=Math.max(.5,zoom-.25);size()};$('fit').onclick=()=>{zoom=1;size()};window.onresize=size;$('viewMode').onchange=()=>{if(busy){$('viewMode').value=String(viewCount);return}viewCount=Number($('viewMode').value);prefs('viewCount',viewCount);render()};$('readingDirection').onchange=()=>{if(busy){$('readingDirection').value=readingDirection;return}readingDirection=$('readingDirection').value;prefs('readingDirection',readingDirection);if(pdf)render();else applyDirection()};$('demo').onclick=async()=>{if(busy)return;if(pdf)await pdf.destroy();if(epubSecond){epubSecond.destroy();epubSecond=null;}if(epub)epub.destroy();epub=null;pdf=img=null;fileKey='';page=total=1;$('filename').textContent='체험용 학습지';render()};window.addEventListener('keydown',e=>{if(/INPUT|BUTTON|SELECT/.test(e.target.tagName))return;if(e.key==='ArrowRight')go(page+viewCount);if(e.key==='ArrowLeft')go(page-viewCount);if(e.code==='Space'){e.preventDefault();hidden=!hidden;paint()}});render();
